def list_tables(project_id, snapshot_id=None, refresh=None, schema=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0198000" if __import__("os").path.isdir("./environment_mix/0198000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if not isinstance(v, str) or not v:
            return None
        try:
            if v.endswith("Z"):
                v = v[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(v)
        except Exception:
            return None

    def _mkid(prefix):
        # ULID-ish, sufficient for offline deterministic uniqueness
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        t = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[t % 32])
            t //= 32
        import secrets
        for _ in range(16):
            out.append(alphabet[secrets.randbelow(32)])
        return prefix + "".join(reversed(out))

    def _b64url_json(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _b64url_json_load(s):
        if not isinstance(s, str) or not s:
            return None
        pad = "=" * (-len(s) % 4)
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def _classify_table_kind(t):
        # best-effort; preserve original row as-is
        if isinstance(t, dict):
            return t.get("type") or t.get("table_type") or t.get("kind")
        return None

    def _get_latest_completed_snapshot(snapshots, proj_id):
        best = None
        best_dt = None
        for s in snapshots:
            if s.get("project_id") != proj_id:
                continue
            if s.get("status") != "completed":
                continue
            dt = _parse_dt(s.get("completed_at") or s.get("updated_at") or s.get("created_at"))
            if dt is None:
                dt = datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            if best is None or dt > best_dt:
                best = s
                best_dt = dt
        return best

    def _complete_snapshot(snap_row):
        # No external DB: "introspection" completes immediately with existing snapshot's latest known data.
        # If there is an older completed snapshot, copy its arrays; otherwise empty arrays.
        snapshots2 = _load("schema_introspection_snapshots.json")
        latest = _get_latest_completed_snapshot(snapshots2, snap_row["project_id"])
        if latest and latest.get("id") != snap_row.get("id"):
            snap_row["tables"] = latest.get("tables") if isinstance(latest.get("tables"), list) else []
            snap_row["extensions"] = latest.get("extensions") if isinstance(latest.get("extensions"), list) else []
            snap_row["migrations"] = latest.get("migrations") if isinstance(latest.get("migrations"), list) else []
        else:
            snap_row["tables"] = snap_row.get("tables") if isinstance(snap_row.get("tables"), list) else []
            snap_row["extensions"] = snap_row.get("extensions") if isinstance(snap_row.get("extensions"), list) else []
            snap_row["migrations"] = snap_row.get("migrations") if isinstance(snap_row.get("migrations"), list) else []
        snap_row["status"] = "completed"
        snap_row["error_message"] = None
        snap_row["completed_at"] = _now_iso()
        snap_row["updated_at"] = _now_iso()
        return snap_row

    t0 = time.time()
    endpoint = "list_tables"
    status_code = "succeeded"
    used_credential = None  # ambient auth; no explicit credential parameter in tool

    try:
        if not isinstance(project_id, str) or not re.match(r"^sup_proj_[0-9A-HJKMNP-TV-Z]{16,}$", project_id or ""):
            status_code = "failed"
            return _err("VALIDATION_ERROR", "Invalid project_id format.")
        if snapshot_id is not None:
            if not isinstance(snapshot_id, str) or not re.match(r"^sup_snap_[0-9A-HJKMNP-TV-Z]{16,}$", snapshot_id or ""):
                status_code = "failed"
                return _err("VALIDATION_ERROR", "Invalid snapshot_id format.")
        if refresh is not None and not isinstance(refresh, bool):
            status_code = "failed"
            return _err("VALIDATION_ERROR", "refresh must be a boolean.")
        if schema is not None and not isinstance(schema, str):
            status_code = "failed"
            return _err("VALIDATION_ERROR", "schema must be a string.")
        if limit is None:
            limit = 100
        if not isinstance(limit, int) or limit < 1 or limit > 500:
            status_code = "failed"
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500.")
        cursor_obj = None
        if cursor is not None:
            cursor_obj = _b64url_json_load(cursor)
            if not isinstance(cursor_obj, dict) or cursor_obj.get("v") != 1 or cursor_obj.get("t") != "tables":
                status_code = "failed"
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            if cursor_obj.get("project_id") != project_id:
                status_code = "failed"
                return _err("VALIDATION_ERROR", "Cursor does not match project_id.")
            if not isinstance(cursor_obj.get("offset"), int) or cursor_obj["offset"] < 0:
                status_code = "failed"
                return _err("VALIDATION_ERROR", "Invalid cursor offset.")

        projects = _load("projects.json")
        proj = None
        for p in projects:
            if p.get("id") == project_id:
                proj = p
                break
        if proj is None:
            status_code = "failed"
            return _err("NOT_FOUND", "Project not found.")

        # Select snapshot
        snapshots = _load("schema_introspection_snapshots.json")
        chosen = None

        if snapshot_id:
            for s in snapshots:
                if s.get("id") == snapshot_id:
                    chosen = s
                    break
            if chosen is None or chosen.get("project_id") != project_id:
                status_code = "failed"
                return _err("NOT_FOUND", "Snapshot not found for project.")
            if chosen.get("status") != "completed":
                status_code = "failed"
                return _err("INVALID_TRANSITION", "Snapshot is not completed.", status=chosen.get("status"))
        else:
            if refresh:
                # create running snapshot, then complete it before returning
                new_snap = {
                    "id": _mkid("sup_snap_"),
                    "project_id": project_id,
                    "source": "on_demand",
                    "pg_version": None,
                    "tables": [],
                    "extensions": [],
                    "migrations": [],
                    "status": "running",
                    "error_message": None,
                    "started_at": _now_iso(),
                    "completed_at": None,
                    "created_at": _now_iso(),
                    "updated_at": _now_iso(),
                }
                snapshots.append(new_snap)
                _save("schema_introspection_snapshots.json", snapshots)

                # transition running -> completed
                new_snap = _complete_snapshot(new_snap)
                # persist update
                for i, s in enumerate(snapshots):
                    if s.get("id") == new_snap["id"]:
                        snapshots[i] = new_snap
                        break
                _save("schema_introspection_snapshots.json", snapshots)
                chosen = new_snap
            else:
                chosen = _get_latest_completed_snapshot(snapshots, project_id)
                if chosen is None:
                    # Must create and complete snapshot before returning results
                    new_snap = {
                        "id": _mkid("sup_snap_"),
                        "project_id": project_id,
                        "source": "on_demand",
                        "pg_version": None,
                        "tables": [],
                        "extensions": [],
                        "migrations": [],
                        "status": "running",
                        "error_message": None,
                        "started_at": _now_iso(),
                        "completed_at": None,
                        "created_at": _now_iso(),
                        "updated_at": _now_iso(),
                    }
                    snapshots.append(new_snap)
                    _save("schema_introspection_snapshots.json", snapshots)

                    new_snap = _complete_snapshot(new_snap)
                    for i, s in enumerate(snapshots):
                        if s.get("id") == new_snap["id"]:
                            snapshots[i] = new_snap
                            break
                    _save("schema_introspection_snapshots.json", snapshots)
                    chosen = new_snap

        tables = chosen.get("tables")
        if not isinstance(tables, list):
            status_code = "failed"
            return _err("VALIDATION_ERROR", "Snapshot tables field is invalid (expected array).")

        # filter schema
        filtered = []
        if schema is None:
            filtered = list(tables)
        else:
            for t in tables:
                if isinstance(t, dict) and t.get("schema") == schema:
                    filtered.append(t)

        # stable order: schema, name, then type if available
        def _key(t):
            if not isinstance(t, dict):
                return ("", "", "")
            return (str(t.get("schema") or ""), str(t.get("name") or ""), str(_classify_table_kind(t) or ""))
        filtered.sort(key=_key)

        offset = 0
        if cursor_obj:
            offset = cursor_obj["offset"]

        page = filtered[offset:offset + limit]
        next_offset = offset + len(page)
        has_more = next_offset < len(filtered)
        next_cursor = _b64url_json({"v": 1, "t": "tables", "project_id": project_id, "snapshot_id": chosen.get("id"), "offset": next_offset}) if has_more else None

        return {
            "tables": page,
            "snapshot_id": chosen.get("id"),
            "project_id": project_id,
            "meta": {
                "total": len(filtered),
                "limit": limit,
                "cursor": cursor,
                "has_more": has_more,
                "next_cursor": next_cursor,
            },
        }
    except Exception as e:
        status_code = "failed"
        return _err("VALIDATION_ERROR", "Unexpected error.", details=str(e))
    finally:
        try:
            # Observable service dynamics: append minimal audit row into db_operations as a "read" operation.
            ops = _load("db_operations.json")
            now = _now_iso()
            op_row = {
                "id": _mkid("sup_op_"),
                "project_id": project_id if isinstance(project_id, str) else "unknown",
                "tool_name": "execute_sql",  # closest enum that exists; mark as read operation for auditing.
                "operation_kind": "read",
                "sql_text": None,
                "migration_name": None,
                "migration_version": None,
                "migration_checksum": None,
                "params": {"endpoint": endpoint, "snapshot_id": snapshot_id, "refresh": refresh, "schema": schema, "limit": limit, "cursor": cursor},
                "result": {"status": status_code},
                "stdout": None,
                "stderr": None,
                "error_message": None if status_code == "succeeded" else "request_failed",
                "status": "succeeded" if status_code == "succeeded" else "failed",
                "started_at": now,
                "finished_at": now,
                "created_at": now,
                "updated_at": now,
            }
            ops.append(op_row)
            _save("db_operations.json", ops)
        except Exception:
            pass

