    t0 = time.time()
    endpoint = "list_extensions"
    status_code = "succeeded"

    try:
        if not isinstance(project_id, str) or not re.match(r"^sup_proj_[0-9A-HJKMNP-TV-Z]{16,}$", project_id or ""):
            status_code = "failed"
            return _err("VALIDATION_ERROR", "Invalid project_id format.")
        if snapshot_id is not None:
            if not isinstance(snapshot_id, str) or not re.match(r"^sup_snap_[0-9A-HJKMNP-TV-Z]{16,}$", snapshot_id or ""):
                status_code = "failed"
                return _err("VALIDATION_ERROR", "Invalid snapshot_id format.")
        if refresh is not None and not isinstance(refresh, bool):
            status_code = "failed"
            return _err("VALIDATION_ERROR", "refresh must be a boolean.")
        if limit is None:
            limit = 100
        if not isinstance(limit, int) or limit < 1 or limit > 500:
            status_code = "failed"
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500.")
        cursor_obj = None
        if cursor is not None:
            cursor_obj = _b64url_json_load(cursor)
            if not isinstance(cursor_obj, dict) or cursor_obj.get("v") != 1 or cursor_obj.get("t") != "extensions":
                status_code = "failed"
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            if cursor_obj.get("project_id") != project_id:
                status_code = "failed"
                return _err("VALIDATION_ERROR", "Cursor does not match project_id.")
            if not isinstance(cursor_obj.get("offset"), int) or cursor_obj["offset"] < 0:
                status_code = "failed"
                return _err("VALIDATION_ERROR", "Invalid cursor offset.")

        projects = _load("projects.json")
        if not any(p.get("id") == project_id for p in projects):
            status_code = "failed"
            return _err("NOT_FOUND", "Project not found.")

        snapshots = _load("schema_introspection_snapshots.json")
        chosen = None

        if snapshot_id:
            for s in snapshots:
                if s.get("id") == snapshot_id:
                    chosen = s
                    break
            if chosen is None or chosen.get("project_id") != project_id:
                status_code = "failed"
                return _err("NOT_FOUND", "Snapshot not found for project.")
            if chosen.get("status") != "completed":
                status_code = "failed"
                return _err("INVALID_TRANSITION", "Snapshot is not completed.", status=chosen.get("status"))
        else:
            if refresh:
                new_snap = {
                    "id": _mkid("sup_snap_"),
                    "project_id": project_id,
                    "source": "on_demand",
                    "pg_version": None,
                    "tables": [],
                    "extensions": [],
                    "migrations": [],
                    "status": "running",
                    "error_message": None,
                    "started_at": _now_iso(),
                    "completed_at": None,
                    "created_at": _now_iso(),
                    "updated_at": _now_iso(),
                }
                snapshots.append(new_snap)
                _save("schema_introspection_snapshots.json", snapshots)

                new_snap = _complete_snapshot(new_snap)
                for i, s in enumerate(snapshots):
                    if s.get("id") == new_snap["id"]:
                        snapshots[i] = new_snap
                        break
                _save("schema_introspection_snapshots.json", snapshots)
                chosen = new_snap
            else:
                chosen = _get_latest_completed_snapshot(snapshots, project_id)
                if chosen is None:
                    new_snap = {
                        "id": _mkid("sup_snap_"),
                        "project_id": project_id,
                        "source": "on_demand",
                        "pg_version": None,
                        "tables": [],
                        "extensions": [],
                        "migrations": [],
                        "status": "running",
                        "error_message": None,
                        "started_at": _now_iso(),
                        "completed_at": None,
                        "created_at": _now_iso(),
                        "updated_at": _now_iso(),
                    }
                    snapshots.append(new_snap)
                    _save("schema_introspection_snapshots.json", snapshots)

                    new_snap = _complete_snapshot(new_snap)
                    for i, s in enumerate(snapshots):
                        if s.get("id") == new_snap["id"]:
                            snapshots[i] = new_snap
                            break
                    _save("schema_introspection_snapshots.json", snapshots)
                    chosen = new_snap

        exts = chosen.get("extensions")
        if not isinstance(exts, list):
            status_code = "failed"
            return _err("VALIDATION_ERROR", "Snapshot extensions field is invalid (expected array).")

        # stable sort by schema+name+version
        def _key(e):
            if not isinstance(e, dict):
                return ("", "", "")
            return (str(e.get("schema") or ""), str(e.get("name") or ""), str(e.get("version") or ""))
        exts_sorted = list(exts)
        exts_sorted.sort(key=_key)

        offset = 0
        if cursor_obj:
            offset = cursor_obj["offset"]

        page = exts_sorted[offset:offset + limit]
        next_offset = offset + len(page)
        has_more = next_offset < len(exts_sorted)
        next_cursor = _b64url_json({"v": 1, "t": "extensions", "project_id": project_id, "snapshot_id": chosen.get("id"), "offset": next_offset}) if has_more else None

        return {
            "extensions": page,
            "snapshot_id": chosen.get("id"),
            "project_id": project_id,
            "meta": {
                "total": len(exts_sorted),
                "limit": limit,
                "cursor": cursor,
                "has_more": has_more,
                "next_cursor": next_cursor,
            },
        }
    except Exception as e:
        status_code = "failed"
        return _err("VALIDATION_ERROR", "Unexpected error.", details=str(e))
    finally:
        try:
            ops = _load("db_operations.json")
            now = _now_iso()
            op_row = {
                "id": _mkid("sup_op_"),
                "project_id": project_id if isinstance(project_id, str) else "unknown",
                "tool_name": "execute_sql",
                "operation_kind": "read",
                "sql_text": None,
                "migration_name": None,
                "migration_version": None,
                "migration_checksum": None,
                "params": {"endpoint": endpoint, "snapshot_id": snapshot_id, "refresh": refresh, "limit": limit, "cursor": cursor},
                "result": {"status": status_code},
                "stdout": None,
                "stderr": None,
                "error_message": None if status_code == "succeeded" else "request_failed",
                "status": "succeeded" if status_code == "succeeded" else "failed",
                "started_at": now,
                "finished_at": now,
                "created_at": now,
                "updated_at": now,
            }
            ops.append(op_row)
            _save("db_operations.json", ops)
        except Exception:
            pass

