        else:
            snap_row["tables"] = snap_row.get("tables") if isinstance(snap_row.get("tables"), list) else []
            snap_row["extensions"] = snap_row.get("extensions") if isinstance(snap_row.get("extensions"), list) else []
            snap_row["migrations"] = snap_row.get("migrations") if isinstance(snap_row.get("migrations"), list) else []
        snap_row["status"] = "completed"
        snap_row["error_message"] = None
        snap_row["completed_at"] = _now_iso()
        snap_row["updated_at"] = _now_iso()
        return snap_row

    endpoint = "list_migrations"
    status_code = "succeeded"

    try:
        if not isinstance(project_id, str) or not re.match(r"^sup_proj_[0-9A-HJKMNP-TV-Z]{16,}$", project_id or ""):
            status_code = "failed"
            return _err("VALIDATION_ERROR", "Invalid project_id format.")
        if snapshot_id is not None:
            if not isinstance(snapshot_id, str) or not re.match(r"^sup_snap_[0-9A-HJKMNP-TV-Z]{16,}$", snapshot_id or ""):
                status_code = "failed"
                return _err("VALIDATION_ERROR", "Invalid snapshot_id format.")
        if refresh is not None and not isinstance(refresh, bool):
            status_code = "failed"
            return _err("VALIDATION_ERROR", "refresh must be a boolean.")
        if status is not None and not isinstance(status, str):
            status_code = "failed"
            return _err("VALIDATION_ERROR", "status must be a string.")
        if limit is None:
            limit = 100
        if not isinstance(limit, int) or limit < 1 or limit > 500:
            status_code = "failed"
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500.")
        cursor_obj = None
        if cursor is not None:
            cursor_obj = _b64url_json_load(cursor)
            if not isinstance(cursor_obj, dict) or cursor_obj.get("v") != 1 or cursor_obj.get("t") != "migrations":
                status_code = "failed"
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            if cursor_obj.get("project_id") != project_id:
                status_code = "failed"
                return _err("VALIDATION_ERROR", "Cursor does not match project_id.")
            if not isinstance(cursor_obj.get("offset"), int) or cursor_obj["offset"] < 0:
                status_code = "failed"
                return _err("VALIDATION_ERROR", "Invalid cursor offset.")

        projects = _load("projects.json")
        if not any(p.get("id") == project_id for p in projects):
            status_code = "failed"
            return _err("NOT_FOUND", "Project not found.")

        snapshots = _load("schema_introspection_snapshots.json")
        chosen = None

        if snapshot_id:
            for s in snapshots:
                if s.get("id") == snapshot_id:
                    chosen = s
                    break
            if chosen is None or chosen.get("project_id") != project_id:
                status_code = "failed"
                return _err("NOT_FOUND", "Snapshot not found for project.")
            if chosen.get("status") != "completed":
                status_code = "failed"
                return _err("INVALID_TRANSITION", "Snapshot is not completed.", status=chosen.get("status"))
        else:
            if refresh:
                new_snap = {
                    "id": _mkid("sup_snap_"),
                    "project_id": project_id,
                    "source": "on_demand",
                    "pg_version": None,
                    "tables": [],
                    "extensions": [],
                    "migrations": [],
                    "status": "running",
                    "error_message": None,
                    "started_at": _now_iso(),
                    "completed_at": None,
                    "created_at": _now_iso(),
                    "updated_at": _now_iso(),
                }
                snapshots.append(new_snap)
                _save("schema_introspection_snapshots.json", snapshots)

                new_snap = _complete_snapshot(new_snap)
                for i, s in enumerate(snapshots):
                    if s.get("id") == new_snap["id"]:
                        snapshots[i] = new_snap
                        break
                _save("schema_introspection_snapshots.json", snapshots)
                chosen = new_snap
            else:
                chosen = _get_latest_completed_snapshot(snapshots, project_id)
                if chosen is None:
                    new_snap = {
                        "id": _mkid("sup_snap_"),
                        "project_id": project_id,
                        "source": "on_demand",
                        "pg_version": None,
                        "tables": [],
                        "extensions": [],
                        "migrations": [],
                        "status": "running",
                        "error_message": None,
                        "started_at": _now_iso(),
                        "completed_at": None,
                        "created_at": _now_iso(),
                        "updated_at": _now_iso(),
                    }
                    snapshots.append(new_snap)
                    _save("schema_introspection_snapshots.json", snapshots)

                    new_snap = _complete_snapshot(new_snap)
                    for i, s in enumerate(snapshots):
                        if s.get("id") == new_snap["id"]:
                            snapshots[i] = new_snap
                            break
                    _save("schema_introspection_snapshots.json", snapshots)
                    chosen = new_snap

        migs = chosen.get("migrations")
        if not isinstance(migs, list):
            status_code = "failed"
            return _err("VALIDATION_ERROR", "Snapshot migrations field is invalid (expected array).")

        filtered = []
        if status is None:
            filtered = list(migs)
        else:
            for m in migs:
                if isinstance(m, dict) and str(m.get("status") or "") == status:
                    filtered.append(m)

        # stable sort: applied_at then version then name
        def _key(m):
            if not isinstance(m, dict):
                return (datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), "", "")
            adt = _parse_dt(m.get("applied_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            return (adt, str(m.get("version") or ""), str(m.get("name") or ""))
        filtered.sort(key=_key)

        offset = 0
        if cursor_obj:
            offset = cursor_obj["offset"]

        page = filtered[offset:offset + limit]
        next_offset = offset + len(page)
        has_more = next_offset < len(filtered)
        next_cursor = _b64url_json({"v": 1, "t": "migrations", "project_id": project_id, "snapshot_id": chosen.get("id"), "offset": next_offset, "status": status}) if has_more else None

        return {
            "migrations": page,
            "snapshot_id": chosen.get("id"),
            "project_id": project_id,
            "meta": {
                "total": len(filtered),
                "limit": limit,
                "cursor": cursor,
                "has_more": has_more,
                "next_cursor": next_cursor,
                "status_filter": status,
            },
        }
    except Exception as e:
        status_code = "failed"
        return _err("VALIDATION_ERROR", "Unexpected error.", details=str(e))
    finally:
        try:
            ops = _load("db_operations.json")
            now = datetime.datetime.now(datetime.timezone.utc).isoformat()
            op_row = {
                "id": _mkid("sup_op_"),
                "project_id": project_id if isinstance(project_id, str) else "unknown",
                "tool_name": "execute_sql",
                "operation_kind": "read",
                "sql_text": None,
                "migration_name": None,
                "migration_version": None,
                "migration_checksum": None,
                "params": {"endpoint": endpoint, "snapshot_id": snapshot_id, "refresh": refresh, "status": status, "limit": limit, "cursor": cursor},
                "result": {"status": status_code},
                "stdout": None,
                "stderr": None,
                "error_message": None if status_code == "succeeded" else "request_failed",
                "status": "succeeded" if status_code == "succeeded" else "failed",
                "started_at": now,
                "finished_at": now,
                "created_at": now,
                "updated_at": now,
            }
            ops.append(op_row)
            _save("db_operations.json", ops)
        except Exception:
            pass

def apply_migration(project_id, migration_name, migration_version, sql, checksum=None, dry_run=None, **_extra):
    import json, os, datetime, re, time, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0198000" if __import__("os").path.isdir("./environment_mix/0198000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "apply_migration"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _reqlog(status, project_row_id=None, message=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + os.urandom(9).hex(),
            "endpoint": endpoint,
            "credential_id": None,
            "project_id": project_row_id,
            "status": status,
            "message": message,
            "extra": extra or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso(),
        })
        _save("request_logs.json", logs)

    def _gen_id(prefix):
        # stable-ish, offline-safe
        return f"{prefix}_{hashlib.sha256(f'{time.time_ns()}:{secrets.token_hex(8)}'.encode()).hexdigest()[:24]}"

    def _get_project(projects, pid):
        for p in projects:
            if isinstance(p, dict) and p.get("id") == pid:
                return p
        return None

    def _branch_deleted(branches, project_id_):
        if not isinstance(branches, list):
            return False
        for b in branches:
            if not isinstance(b, dict):
                continue
            if b.get("branch_project_id") == project_id_ and b.get("status") in ("deleted", "deleting"):
                return True
        return False

    def _strip_leading_comments(s):
        # best-effort remove leading whitespace/comments
        s = (s or "").lstrip("\ufeff")
        return re.sub(r"^\s*(--[^\n]*\n|/\*.*?\*/\s*)+", "", s, flags=re.S | re.M).lstrip()

    # Validate inputs
    if not isinstance(project_id, str) or not re.match(r"^sup_proj_[0-9A-HJKMNP-TV-Z]{16,}$", project_id or ""):
        _reqlog("VALIDATION_ERROR", None, "Malformed project_id", {"field": "project_id"})
        return _err("VALIDATION_ERROR", "Malformed project_id.", field="project_id")
    if not isinstance(migration_name, str) or not migration_name.strip():
        _reqlog("VALIDATION_ERROR", project_id, "Missing migration_name", {"field": "migration_name"})
        return _err("VALIDATION_ERROR", "migration_name is required.", field="migration_name")
    if not isinstance(migration_version, str) or not migration_version.strip():
        _reqlog("VALIDATION_ERROR", project_id, "Missing migration_version", {"field": "migration_version"})
        return _err("VALIDATION_ERROR", "migration_version is required.", field="migration_version")
    if not isinstance(sql, str) or not sql.strip():
        _reqlog("VALIDATION_ERROR", project_id, "Missing sql", {"field": "sql"})
        return _err("VALIDATION_ERROR", "sql is required.", field="sql")
    if len(sql) > 200000:
        _reqlog("VALIDATION_ERROR", project_id, "sql too long", {"field": "sql", "max": 200000})
        return _err("VALIDATION_ERROR", "sql exceeds maximum length (200000).", field="sql", max=200000)
    if checksum is not None and not isinstance(checksum, str):
        _reqlog("VALIDATION_ERROR", project_id, "checksum must be string", {"field": "checksum"})
        return _err("VALIDATION_ERROR", "checksum must be a string.", field="checksum")
    if dry_run is None:
        dry_run = False
    if not isinstance(dry_run, bool):
        _reqlog("VALIDATION_ERROR", project_id, "dry_run must be boolean", {"field": "dry_run"})
        return _err("VALIDATION_ERROR", "dry_run must be a boolean.", field="dry_run")

    # Load store rows
    projects = _load("projects.json")
    branches = _load("branches.json")
    dbops = _load("db_operations.json")
    snapshots = _load("schema_introspection_snapshots.json")
    if not isinstance(projects, list) or not isinstance(branches, list) or not isinstance(dbops, list) or not isinstance(snapshots, list):
        _reqlog("CONFLICT", project_id, "Datastore corrupted")
        return _err("CONFLICT", "Datastore is not in the expected format.")

    proj = _get_project(projects, project_id)
    if not proj:
        _reqlog("NOT_FOUND", project_id, "Project not found")
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)

    # reject operations against deleted branches
    if _branch_deleted(branches, project_id):
        _reqlog("UNAUTHORIZED", project_id, "Branch project deleted/deleting")
        return _err("UNAUTHORIZED", "Branch project is deleted or deleting.")

    # Business rule: apply_migration creates db_operations row with tool_name=apply_migration, operation_kind=ddl.
    # The audit shows apply_migration was being incorrectly restricted to "DDL only". Relax:
    # allow any SQL text; operation_kind fixed to 'ddl' by rule (this tool is the gate for schema changes), even if SQL is DML.
    # Still reject clearly empty/bad inputs only (done above).
    sql_clean = _strip_leading_comments(sql)

    now = _now_iso()
    op_id = _gen_id("dbop")

    op = {
        "id": op_id,
        "project_id": project_id,
        "tool_name": "apply_migration",
        "operation_kind": "ddl",
        "sql_text": sql_clean,
        "migration_name": migration_name.strip(),
        "migration_version": migration_version.strip(),
        "migration_checksum": checksum,
        "params": {"dry_run": dry_run},
        "result": None,
        "stdout": None,
        "stderr": None,
        "error_message": None,
        "status": "queued",
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    dbops.append(op)
    _save("db_operations.json", dbops)

    # Transition queued -> running
    op["status"] = "running"
    op["started_at"] = _now_iso()
    op["updated_at"] = op["started_at"]
    _save("db_operations.json", dbops)

    # Execute (offline): dry_run just validates/plans; non-dry_run "succeeds" and writes snapshot trigger.
    # We must always finalize the operation with finished_at and status.
    try:
        # minimal "validation": ensure it looks like SQL, not too large already checked
        head = _strip_leading_comments(sql_clean).lower()
        if not head:
            raise ValueError("SQL is empty after stripping comments.")
        # deterministic-ish outcome
        if dry_run:
            res = {
                "dry_run": True,
                "planned": True,
                "migration": {
                    "name": op["migration_name"],
                    "version": op["migration_version"],
                    "checksum": op["migration_checksum"],
                },
                "note": "Dry run: no changes applied."
            }
        else:
            res = {
                "dry_run": False,
                "applied": True,
                "migration": {
                    "name": op["migration_name"],
                    "version": op["migration_version"],
                    "checksum": op["migration_checksum"],
                }
            }

        op["result"] = res
        op["status"] = "succeeded"
        op["finished_at"] = _now_iso()
        op["updated_at"] = op["finished_at"]
    except Exception as e:
        op["status"] = "failed"
        op["error_message"] = str(e)
        op["finished_at"] = _now_iso()
        op["updated_at"] = op["finished_at"]

    _save("db_operations.json", dbops)

    # On success and not dry_run: trigger a new schema_introspection_snapshots row with source='post_migration'
    if op["status"] == "succeeded" and not dry_run:
        snap_id = _gen_id("snap")
        ts = _now_iso()
        snap = {
            "id": snap_id,
            "project_id": project_id,
            "source": "post_migration",
            "pg_version": None,
            "tables": [],
            "extensions": [],
            "migrations": [],
            "status": "completed",
            "error_message": None,
            "started_at": ts,
            "completed_at": ts,
            "created_at": ts,
            "updated_at": ts,
        }
        snapshots.append(snap)
        _save("schema_introspection_snapshots.json", snapshots)

    _reqlog("OK" if op["status"] == "succeeded" else "FAILED", project_id, None, {"db_operation_id": op_id})
    return {"db_operation": op}

def execute_sql(project_id, sql, params=None, read_only=None, **_extra):
    import json, os, datetime, re, time, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0198000" if __import__("os").path.isdir("./environment_mix/0198000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "execute_sql"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _reqlog(status, project_row_id=None, message=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + os.urandom(9).hex(),
            "endpoint": endpoint,
            "credential_id": None,
            "project_id": project_row_id,
            "status": status,
            "message": message,
            "extra": extra or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso(),
        })
        _save("request_logs.json", logs)

    def _gen_id(prefix):
        return f"{prefix}_{hashlib.sha256(f'{time.time_ns()}:{secrets.token_hex(8)}'.encode()).hexdigest()[:24]}"

    def _strip_leading_comments(s):
        s = (s or "").lstrip("\ufeff")
        return re.sub(r"^\s*(--[^\n]*\n|/\*.*?\*/\s*)+", "", s, flags=re.S | re.M).lstrip()

    def _classify(sql_text):
        s2 = _strip_leading_comments(sql_text)
        up = s2.upper()
        if not up:
            return None, None
        # treat multiple statements conservatively by looking at first token
        m = re.match(r"^([A-Z]+)", up)
        kw = m.group(1) if m else None
        ddl = {"CREATE", "ALTER", "DROP", "TRUNCATE", "REINDEX", "VACUUM", "CLUSTER", "COMMENT", "GRANT", "REVOKE", "DISCARD"}
        if kw in ddl or up.startswith("DO "):
            return "ddl", (f"Statement classified as DDL ({kw})" if kw else "Statement classified as DDL")
        if kw in {"SELECT", "WITH", "SHOW", "EXPLAIN"}:
            return "read", None
        if kw in {"INSERT", "UPDATE", "DELETE"}:
            return "dml", None
        # unknown: treat as dml for safety
        return "dml", None

    # Validate inputs
    if not isinstance(project_id, str) or not re.match(r"^sup_proj_[0-9A-HJKMNP-TV-Z]{16,}$", project_id or ""):
        _reqlog("VALIDATION_ERROR", None, "Malformed project_id", {"field": "project_id"})
        return _err("VALIDATION_ERROR", "Malformed project_id.", field="project_id")
    if not isinstance(sql, str) or not sql.strip():
        _reqlog("VALIDATION_ERROR", project_id, "Missing sql", {"field": "sql"})
        return _err("VALIDATION_ERROR", "Missing or empty SQL.", field="sql")
    if len(sql) > 200000:
        _reqlog("VALIDATION_ERROR", project_id, "sql too long", {"field": "sql", "max": 200000})
        return _err("VALIDATION_ERROR", "sql exceeds maximum length (200000).", field="sql", max=200000)
    if params is None:
        params = {}
    if not isinstance(params, dict):
        _reqlog("VALIDATION_ERROR", project_id, "params must be object", {"field": "params"})
        return _err("VALIDATION_ERROR", "params must be an object.", field="params")
    if read_only is None:
        read_only = False
    if not isinstance(read_only, bool):
        _reqlog("VALIDATION_ERROR", project_id, "read_only must be boolean", {"field": "read_only"})
        return _err("VALIDATION_ERROR", "read_only must be a boolean.", field="read_only")

    projects = _load("projects.json")
    branches = _load("branches.json")
    dbops = _load("db_operations.json")
    if not isinstance(projects, list) or not isinstance(branches, list) or not isinstance(dbops, list):
        _reqlog("CONFLICT", project_id, "Datastore corrupted")
        return _err("CONFLICT", "Datastore is not in the expected format.")

    # FIX: match by projects.id (not project_ref)
    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not proj:
        _reqlog("NOT_FOUND", project_id, "Project not found")
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)

    # reject operations against deleted branches
    for b in branches:
        if isinstance(b, dict) and b.get("branch_project_id") == project_id and b.get("status") in ("deleted", "deleting"):
            _reqlog("UNAUTHORIZED", project_id, "Branch project deleted/deleting", {"branch_status": b.get("status")})
            return _err("UNAUTHORIZED", "Branch project is deleted or deleting.", branch_status=b.get("status"))

    kind, reason = _classify(sql)
    if kind == "ddl":
        _reqlog("VALIDATION_ERROR", project_id, "DDL rejected; use apply_migration")
        return _err("VALIDATION_ERROR", "execute_sql does not allow DDL; use apply_migration.", reason=reason)

    # best-effort read_only enforcement: reject obvious writes if read_only
    if read_only and kind == "dml":
        _reqlog("VALIDATION_ERROR", project_id, "read_only forbids DML")
        return _err("VALIDATION_ERROR", "read_only execution forbids write statements.", field="read_only")

    now = _now_iso()
    op_id = _gen_id("dbop")
    op = {
        "id": op_id,
        "project_id": project_id,
        "tool_name": "execute_sql",
        "operation_kind": kind or "dml",
        "sql_text": _strip_leading_comments(sql),
        "migration_name": None,
        "migration_version": None,
        "migration_checksum": None,
        "params": {"params": params, "read_only": read_only},
        "result": None,
        "stdout": None,
        "stderr": None,
        "error_message": None,
        "status": "queued",
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    dbops.append(op)
    _save("db_operations.json", dbops)

    # queued -> running
    op["status"] = "running"
    op["started_at"] = _now_iso()
    op["updated_at"] = op["started_at"]
    _save("db_operations.json", dbops)

    # Offline execution simulation: we can't run SQL; return structured outcome
    try:
        res = {
            "classification": kind or "dml",
            "read_only": read_only,
            "params": params,
            "rows": [],
            "row_count": 0,
            "notice": "Executed by MCP offline simulator; no real database connection configured."
        }
        op["result"] = res
        op["status"] = "succeeded"
        op["finished_at"] = _now_iso()
        op["updated_at"] = op["finished_at"]
    except Exception as e:
        op["status"] = "failed"
        op["error_message"] = str(e)
        op["finished_at"] = _now_iso()
        op["updated_at"] = op["finished_at"]

    _save("db_operations.json", dbops)
    _reqlog("OK" if op["status"] == "succeeded" else "FAILED", project_id, None, {"db_operation_id": op_id})
    return {"db_operation": op}

def list_edge_functions(project_id, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0198000" if __import__("os").path.isdir("./environment_mix/0198000") else "/app/database")
    def _load(n):
