    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _reqlog(status_code, project_row_id=None, message=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + os.urandom(9).hex(),
            "endpoint": endpoint,
            "credential_id": None,
            "project_id": project_row_id,
            "status": status_code,
            "message": message,
            "extra": extra or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso(),
        })
        _save("request_logs.json", logs)

    # Validate
    if not isinstance(project_id, str) or not re.match(r"^sup_proj_[0-9A-HJKMNP-TV-Z]{16,}$", project_id or ""):
        _reqlog("VALIDATION_ERROR", None, "Malformed project_id", {"field": "project_id"})
        return _err("VALIDATION_ERROR", "Malformed project_id.", field="project_id")
    if status is not None and status not in ("active", "archived"):
        _reqlog("VALIDATION_ERROR", project_id, "Invalid status", {"field": "status"})
        return _err("VALIDATION_ERROR", "Invalid status.", field="status", allowed=["active", "archived"])
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _reqlog("VALIDATION_ERROR", project_id, "limit out of range", {"field": "limit"})
        return _err("VALIDATION_ERROR", "limit out of range (1..200).", field="limit")
    if cursor is not None and (not isinstance(cursor, str) or cursor == ""):
        _reqlog("VALIDATION_ERROR", project_id, "Invalid cursor", {"field": "cursor"})
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string.", field="cursor")

    projects = _load("projects.json")
    branches = _load("branches.json")
    funcs = _load("edge_functions.json")
    if not isinstance(projects, list) or not isinstance(branches, list) or not isinstance(funcs, list):
        _reqlog("CONFLICT", project_id, "Datastore corrupted")
        return _err("CONFLICT", "Datastore is not in the expected format.")

    # FIX: match by projects.id (not project_ref)
    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not proj:
        _reqlog("NOT_FOUND", project_id, "Project not found")
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)

    # reject operations against deleted branches
    for b in branches:
        if isinstance(b, dict) and b.get("branch_project_id") == project_id and b.get("status") in ("deleted", "deleting"):
            _reqlog("UNAUTHORIZED", project_id, "Branch project deleted/deleting", {"branch_status": b.get("status")})
            return _err("UNAUTHORIZED", "Branch project is deleted or deleting.", branch_status=b.get("status"))

    rows = [f for f in funcs if isinstance(f, dict) and f.get("project_id") == project_id]
    if status is not None:
        rows = [f for f in rows if f.get("status") == status]

    # deterministic ordering for pagination: updated_at desc then id
    def _key(r):
        return (r.get("updated_at") or "", r.get("id") or "")
    rows.sort(key=_key, reverse=True)

    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            # format: "i:<index>"
            if raw.startswith("i:"):
                start = int(raw[2:])
        except Exception:
            _reqlog("VALIDATION_ERROR", project_id, "Malformed cursor", {"field": "cursor"})
            return _err("VALIDATION_ERROR", "Malformed cursor.", field="cursor")

    page = rows[start:start + limit]
    next_cursor = None
    if start + limit < len(rows):
        next_cursor = base64.urlsafe_b64encode(f"i:{start+limit}".encode("utf-8")).decode("utf-8").rstrip("=")

    _reqlog("OK", project_id, None, {"returned": len(page), "total": len(rows)})
    return {
        "data": page,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "has_more": (next_cursor is not None),
            "next_cursor": next_cursor
        }
    }

def deploy_edge_function(project_id, slug, source_text, description=None, entrypoint_path=None, runtime=None, deploy_metadata=None, **_extra):
    import json, os, datetime, time, re, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0198000" if __import__("os").path.isdir("./environment_mix/0198000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "deploy_edge_function"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _reqlog(status_code, project_row_id=None, message=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + os.urandom(9).hex(),
            "endpoint": endpoint,
            "credential_id": None,
            "project_id": project_row_id,
            "status": status_code,
            "message": message,
            "extra": extra or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso(),
        })
        _save("request_logs.json", logs)

    def _gen_id(prefix):
        return f"{prefix}_{hashlib.sha256(f'{time.time_ns()}:{secrets.token_hex(8)}'.encode()).hexdigest()[:24]}"

    # Validate
    if not isinstance(project_id, str) or not re.match(r"^sup_proj_[0-9A-HJKMNP-TV-Z]{16,}$", project_id or ""):
        _reqlog("VALIDATION_ERROR", None, "Malformed project_id", {"field": "project_id"})
        return _err("VALIDATION_ERROR", "Malformed project_id.", field="project_id")
    if not isinstance(slug, str) or not slug.strip():
        _reqlog("VALIDATION_ERROR", project_id, "Missing slug", {"field": "slug"})
        return _err("VALIDATION_ERROR", "Missing/empty slug.", field="slug")
    slug = slug.strip()
    if not re.match(r"^[a-z0-9][a-z0-9_-]{0,62}$", slug):
        _reqlog("VALIDATION_ERROR", project_id, "Invalid slug pattern", {"field": "slug"})
        return _err("VALIDATION_ERROR", "slug does not match required pattern.", field="slug", pattern="^[a-z0-9][a-z0-9_-]{0,62}$")
    if not isinstance(source_text, str) or not source_text.strip():
        _reqlog("VALIDATION_ERROR", project_id, "Missing source_text", {"field": "source_text"})
        return _err("VALIDATION_ERROR", "Missing/empty source_text.", field="source_text")
    if len(source_text) > 500000:
        _reqlog("VALIDATION_ERROR", project_id, "source_text too long", {"field": "source_text", "max": 500000})
        return _err("VALIDATION_ERROR", "source_text too long (max 500000).", field="source_text", max=500000)
    if description is not None and not isinstance(description, str):
        _reqlog("VALIDATION_ERROR", project_id, "description must be string", {"field": "description"})
        return _err("VALIDATION_ERROR", "description must be a string.", field="description")
    if entrypoint_path is not None and not isinstance(entrypoint_path, str):
        _reqlog("VALIDATION_ERROR", project_id, "entrypoint_path must be string", {"field": "entrypoint_path"})
        return _err("VALIDATION_ERROR", "entrypoint_path must be a string.", field="entrypoint_path")
    if runtime is None:
        runtime = "deno-edge"
    if runtime not in ("deno-edge",):
        _reqlog("VALIDATION_ERROR", project_id, "Invalid runtime", {"field": "runtime"})
        return _err("VALIDATION_ERROR", "Invalid runtime.", field="runtime", allowed=["deno-edge"])
    if deploy_metadata is None:
        deploy_metadata = {}
    if not isinstance(deploy_metadata, dict):
        _reqlog("VALIDATION_ERROR", project_id, "deploy_metadata must be object", {"field": "deploy_metadata"})
        return _err("VALIDATION_ERROR", "deploy_metadata must be an object.", field="deploy_metadata")

    projects = _load("projects.json")
    branches = _load("branches.json")
    funcs = _load("edge_functions.json")
    vers = _load("edge_function_versions.json")
    if not isinstance(projects, list) or not isinstance(branches, list) or not isinstance(funcs, list) or not isinstance(vers, list):
        _reqlog("CONFLICT", project_id, "Datastore corrupted")
        return _err("CONFLICT", "Datastore is not in the expected format.")

    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not proj:
        _reqlog("NOT_FOUND", project_id, "Project not found")
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)

    for b in branches:
        if isinstance(b, dict) and b.get("branch_project_id") == project_id and b.get("status") in ("deleted", "deleting"):
            _reqlog("UNAUTHORIZED", project_id, "Branch project deleted/deleting", {"branch_status": b.get("status")})
            return _err("UNAUTHORIZED", "Branch project is deleted or deleting.", branch_status=b.get("status"))

    # Upsert edge_functions by (project_id, slug)
    fn = next((f for f in funcs if isinstance(f, dict) and f.get("project_id") == project_id and f.get("slug") == slug), None)
    now = _now_iso()

    if fn is None:
        fn = {
            "id": _gen_id("efn"),
            "project_id": project_id,
            "slug": slug,
            "description": description,
            "entrypoint_path": entrypoint_path,
            "active_version_id": None,
            "runtime": runtime,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        funcs.append(fn)
    else:
        # update mutable fields
        if description is not None:
            fn["description"] = description
        if entrypoint_path is not None:
            fn["entrypoint_path"] = entrypoint_path
        fn["runtime"] = runtime
        fn["updated_at"] = now
        # if archived, keep as-is (caller can deploy to archived? allow but doesn't change status unless explicitly required)
        if fn.get("status") not in ("active", "archived"):
            fn["status"] = "active"

    # Create new version with version_number=max+1
    fn_id = fn["id"]
    prev_versions = [v for v in vers if isinstance(v, dict) and v.get("function_id") == fn_id]
    max_vn = 0
    for v in prev_versions:
        vn = v.get("version_number")
        if isinstance(vn, int) and vn > max_vn:
            max_vn = vn
    new_vn = max_vn + 1
    bundle_sha = hashlib.sha256(source_text.encode("utf-8")).hexdigest()
    ver_id = _gen_id("efv")
    ver = {
        "id": ver_id,
        "function_id": fn_id,
        "project_id": project_id,
        "version_number": new_vn,
        "source_bundle_sha256": bundle_sha,
        "source_text": source_text,
        "deploy_metadata": deploy_metadata,
        "status": "deployed",
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }

    # Supersede prior active version if any
    prior_active_id = fn.get("active_version_id")
    if prior_active_id:
        for v in vers:
            if isinstance(v, dict) and v.get("id") == prior_active_id and v.get("function_id") == fn_id:
                if v.get("status") == "deployed":
                    v["status"] = "superseded"
                    v["updated_at"] = now
                break

    vers.append(ver)
    fn["active_version_id"] = ver_id
    fn["updated_at"] = now

    _save("edge_functions.json", funcs)
    _save("edge_function_versions.json", vers)

    _reqlog("OK", project_id, None, {"function_id": fn_id, "version_id": ver_id, "version_number": new_vn})
    return {"function": fn, "version": ver}

def get_logs(project_id, service, since_seconds=None, limit=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0198000" if __import__("os").path.isdir("./environment_mix/0198000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "get_logs"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _reqlog(status_code, project_row_id=None, message=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + os.urandom(9).hex(),
            "endpoint": endpoint,
            "credential_id": None,
            "project_id": project_row_id,
            "status": status_code,
            "message": message,
            "extra": extra or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso(),
        })
        _save("request_logs.json", logs)

    # Validate
    if not isinstance(project_id, str) or not re.match(r"^sup_proj_[0-9A-HJKMNP-TV-Z]{16,}$", project_id or ""):
        _reqlog("VALIDATION_ERROR", None, "Malformed project_id", {"field": "project_id"})
        return _err("VALIDATION_ERROR", "Malformed project_id.", field="project_id")
    if not isinstance(service, str) or not service.strip():
        _reqlog("VALIDATION_ERROR", project_id, "Missing/invalid service", {"field": "service"})
        return _err("VALIDATION_ERROR", "Missing/invalid service.", field="service")
    service = service.strip()
    if since_seconds is None:
        since_seconds = 10
    if not isinstance(since_seconds, int) or since_seconds < 1 or since_seconds > 60:
        _reqlog("VALIDATION_ERROR", project_id, "since_seconds out of range", {"field": "since_seconds"})
        return _err("VALIDATION_ERROR", "since_seconds out of range (1..60).", field="since_seconds")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _reqlog("VALIDATION_ERROR", project_id, "limit out of range", {"field": "limit"})
        return _err("VALIDATION_ERROR", "limit out of range (1..200).", field="limit")

    projects = _load("projects.json")
    branches = _load("branches.json")
    dbops = _load("db_operations.json")
    if not isinstance(projects, list) or not isinstance(branches, list) or not isinstance(dbops, list):
        _reqlog("CONFLICT", project_id, "Datastore corrupted")
        return _err("CONFLICT", "Datastore is not in the expected format.")

    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not proj:
        _reqlog("NOT_FOUND", project_id, "Project not found")
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)

    for b in branches:
        if isinstance(b, dict) and b.get("branch_project_id") == project_id and b.get("status") in ("deleted", "deleting"):
            _reqlog("UNAUTHORIZED", project_id, "Branch project deleted/deleting", {"branch_status": b.get("status")})
            return _err("UNAUTHORIZED", "Branch project is deleted or deleting.", branch_status=b.get("status"))

    # Ephemeral logs: derive from db_operations created/updated within window. Do not persist logs elsewhere.
    now = datetime.datetime.now(datetime.timezone.utc)
    window_start = now - datetime.timedelta(seconds=since_seconds)

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    lines = []
    for op in dbops:
        if not isinstance(op, dict):
            continue
        if op.get("project_id") != project_id:
            continue
        ts = _parse_dt(op.get("updated_at") or op.get("created_at"))
        if ts is None or ts < window_start:
            continue
        # service filter: map operation/tool to a service-ish label
        svc = "db"
        if service.lower() in ("db", "database", "postgres"):
            pass
        elif service.lower() in ("api", "auth", "functions", "edge", "realtime", "storage"):
            # no real provider; return empty for non-db services
            continue

        msg = f"{op.get('tool_name')} {op.get('status')} id={op.get('id')}"
        if op.get("error_message"):
            msg += f" error={op.get('error_message')}"
        lines.append({
            "timestamp": (ts.astimezone(datetime.timezone.utc).isoformat()),
            "service": svc,
            "message": msg
        })

    lines.sort(key=lambda x: x.get("timestamp", ""), reverse=True)
    lines = lines[:limit]

    _reqlog("OK", project_id, None, {"returned": len(lines), "since_seconds": since_seconds, "service": service})
    return {"data": lines, "meta": {"limit": limit, "since_seconds": since_seconds}}

