    if not isinstance(project_id, str) or not re.match(r"^sup_proj_[0-9A-HJKMNP-TV-Z]{16,26}$", project_id or ""):
        _reqlog("VALIDATION_ERROR", None, "Malformed project_id", {"field": "project_id"})
        return _err("VALIDATION_ERROR", "Malformed project_id.", field="project_id")
    allowed_status = ("creating", "ready", "merging", "rebasing", "resetting", "deleting", "deleted", "failed")
    if status is not None and status not in allowed_status:
        _reqlog("VALIDATION_ERROR", project_id, "Invalid status filter", {"field": "status"})
        return _err("VALIDATION_ERROR", "Invalid status.", field="status", allowed=list(allowed_status))
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _reqlog("VALIDATION_ERROR", project_id, "limit out of range", {"field": "limit"})
        return _err("VALIDATION_ERROR", "limit out of range (1..100).", field="limit")
    if sort is None:
        sort = "created_at"
    if sort not in ("created_at", "updated_at", "name"):
        _reqlog("VALIDATION_ERROR", project_id, "Invalid sort", {"field": "sort"})
        return _err("VALIDATION_ERROR", "Invalid sort.", field="sort", allowed=["created_at", "updated_at", "name"])
    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        _reqlog("VALIDATION_ERROR", project_id, "Invalid order", {"field": "order"})
        return _err("VALIDATION_ERROR", "Invalid order.", field="order", allowed=["asc", "desc"])
    if cursor is not None and (not isinstance(cursor, str) or cursor == ""):
        _reqlog("VALIDATION_ERROR", project_id, "Invalid cursor", {"field": "cursor"})
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string.", field="cursor")

    projects = _load("projects.json")
    branches = _load("branches.json")
    if not isinstance(projects, list) or not isinstance(branches, list):
        _reqlog("CONFLICT", project_id, "Datastore corrupted")
        return _err("CONFLICT", "Datastore is not in the expected format.")

    prod = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not prod:
        _reqlog("NOT_FOUND", project_id, "Project not found")
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)
    if prod.get("environment") != "production":
        # The API expects production project_id
        _reqlog("VALIDATION_ERROR", project_id, "project_id must be a production project")
        return _err("VALIDATION_ERROR", "project_id must reference a production project.", field="project_id")

    rows = [b for b in branches if isinstance(b, dict) and b.get("production_project_id") == project_id]
    if status is not None:
        rows = [b for b in rows if b.get("status") == status]

    def _k(b):
        v = b.get(sort)
        if v is None:
            v = ""
        return (v, b.get("id") or "")
    rows.sort(key=_k, reverse=(order == "desc"))

    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            if raw.startswith("i:"):
                start = int(raw[2:])
        except Exception:
            _reqlog("VALIDATION_ERROR", project_id, "Malformed cursor", {"field": "cursor"})
            return _err("VALIDATION_ERROR", "Malformed cursor.", field="cursor")

    page = rows[start:start + limit]
    next_cursor = None
    if start + limit < len(rows):
        next_cursor = base64.urlsafe_b64encode(f"i:{start+limit}".encode("utf-8")).decode("utf-8").rstrip("=")

    _reqlog("OK", project_id, None, {"returned": len(page), "total": len(rows)})
    return {
        "data": page,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "has_more": (next_cursor is not None),
            "next_cursor": next_cursor,
            "sort": sort,
            "order": order
        }
    }

def delete_branch(branch_id, **_extra):
    import json, os, datetime, re, time, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0198000" if __import__("os").path.isdir("./environment_mix/0198000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "delete_branch"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _reqlog(status_code, project_row_id=None, message=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + os.urandom(9).hex(),
            "endpoint": endpoint,
            "credential_id": None,
            "project_id": project_row_id,
            "status": status_code,
            "message": message,
            "extra": extra or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso(),
        })
        _save("request_logs.json", logs)

    def _gen_id(prefix):
        return f"{prefix}_{hashlib.sha256(f'{time.time_ns()}:{secrets.token_hex(8)}'.encode()).hexdigest()[:24]}"

    # IMPORTANT FIX: datastore/audit calls pass a project_id-like value as branch_id.
    # Accept either branches.id (sup_br_...) OR a branch project id (sup_proj_...) and resolve to the branch row.
    if not isinstance(branch_id, str) or not branch_id.strip():
        _reqlog("VALIDATION_ERROR", None, "Invalid branch_id", {"field": "branch_id"})
        return _err("VALIDATION_ERROR", "branch_id must be a non-empty string.", field="branch_id")

    bid = branch_id.strip()
    is_branch_ulid = re.match(r"^sup_br_[0-9A-HJKMNP-TV-Z]{16,26}$", bid or "") is not None
    is_proj_ulid = re.match(r"^sup_proj_[0-9A-HJKMNP-TV-Z]{16,}$", bid or "") is not None
    if not (is_branch_ulid or is_proj_ulid):
        _reqlog("VALIDATION_ERROR", None, "Invalid branch_id format", {"field": "branch_id"})
        return _err("VALIDATION_ERROR", "Invalid branch_id.", field="branch_id")

    branches = _load("branches.json")
    projects = _load("projects.json")
    if not isinstance(branches, list) or not isinstance(projects, list):
        _reqlog("CONFLICT", None, "Datastore corrupted")
        return _err("CONFLICT", "Datastore is not in the expected format.")

    branch = None
    if is_branch_ulid:
        branch = next((b for b in branches if isinstance(b, dict) and b.get("id") == bid), None)
    else:
        # treat as branch_project_id
        branch = next((b for b in branches if isinstance(b, dict) and b.get("branch_project_id") == bid), None)

    if not branch:
        _reqlog("NOT_FOUND", None, "Branch not found", {"branch_id": bid})
        return _err("NOT_FOUND", "Branch not found.", branch_id=bid)

    # conflict states
    st = branch.get("status")
    if st == "deleted":
        _reqlog("CONFLICT", branch.get("branch_project_id"), "Branch already deleted")
        return _err("CONFLICT", "Branch already deleted.")
    if st in ("merging", "rebasing", "resetting", "creating"):
        _reqlog("CONFLICT", branch.get("branch_project_id"), "Branch has in-progress operation", {"status": st})
        return _err("CONFLICT", "Branch is in a non-deletable in-progress state.", status=st)

    now = _now_iso()

    # Transition to deleting then deleted (immediate in offline model)
    # Enforce lifecycle transitions
    # ready/failed -> deleting
    if st not in ("ready", "failed", "deleting"):
        _reqlog("INVALID_TRANSITION", branch.get("branch_project_id"), "Invalid transition to deleting", {"status": st})
        return _err("INVALID_TRANSITION", "Branch status cannot transition to deleting from current state.", status=st)

    if st != "deleting":
        branch["status"] = "deleting"
        branch["updated_at"] = now

    # mark deleted
    branch["status"] = "deleted"
    branch["updated_at"] = _now_iso()

    # Update corresponding branch project: transition to deleting then disabled (or keep deleting), but do not remove row (no file delete rule)
    bp_id = branch.get("branch_project_id")
    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == bp_id), None)
    if proj:
        # lifecycle transitions: active/disabled -> deleting allowed; deleting terminal
        pstat = proj.get("status")
        if pstat in ("active", "disabled"):
            proj["status"] = "deleting"
            proj["updated_at"] = _now_iso()
        # after delete, disable it for safety if possible
        if proj.get("status") == "deleting":
            # cannot transition deleting -> disabled per schema, so keep as deleting
            proj["updated_at"] = _now_iso()

    _save("branches.json", branches)
    _save("projects.json", projects)

    _reqlog("OK", bp_id, None, {"branch_id": branch.get("id"), "branch_project_id": bp_id})
    return {"branch": branch}

