    if br.get("status") != "ready":
        _reqlog("CONFLICT", br.get("branch_project_id"), "Branch not rebaseable", {"status": br.get("status")})
        return _err("CONFLICT", "Branch is not in a rebaseable state.", status=br.get("status"))

    # start rebasing
    br["status"] = "rebasing"
    br["updated_at"] = _now_iso()
    _save("branches.json", branches)

    prod_id = br.get("production_project_id")
    branch_pid = br.get("branch_project_id")

    def _latest_completed(pid):
        c = [s for s in snaps if isinstance(s, dict) and s.get("project_id") == pid and s.get("status") == "completed"]
        c.sort(key=lambda x: x.get("completed_at") or x.get("updated_at") or x.get("created_at") or "", reverse=True)
        return c[0] if c else None

    try:
        psnap = _latest_completed(prod_id)
        bsnap = _latest_completed(branch_pid)

        pm = psnap.get("migrations") if psnap and isinstance(psnap.get("migrations"), list) else []
        bm = bsnap.get("migrations") if bsnap and isinstance(bsnap.get("migrations"), list) else []

        # Detect checksum conflicts: same version but different checksum
        pm_by_ver = {}
        for m in pm:
            if isinstance(m, dict) and m.get("version") is not None:
                pm_by_ver[m.get("version")] = m.get("checksum")
        for m in bm:
            if isinstance(m, dict) and m.get("version") is not None and m.get("checksum") is not None:
                v = m.get("version")
                if v in pm_by_ver and pm_by_ver[v] is not None and pm_by_ver[v] != m.get("checksum"):
                    raise ValueError(f"Migration checksum conflict for version {v}")

        # Apply missing production migrations onto branch (by version+checksum tuple)
        bm_index = {(m.get("version"), m.get("checksum")) for m in bm if isinstance(m, dict)}
        to_add = [m for m in pm if isinstance(m, dict) and (m.get("version"), m.get("checksum")) not in bm_index]
        new_bm = bm + to_add

        # Refresh branch snapshot after "apply"
        ts = _now_iso()
        snaps.append({
            "id": _gen_id("snap"),
            "project_id": branch_pid,
            "source": "post_migration",
            "pg_version": bsnap.get("pg_version") if bsnap else (psnap.get("pg_version") if psnap else None),
            "tables": bsnap.get("tables") if bsnap and isinstance(bsnap.get("tables"), list) else [],
            "extensions": bsnap.get("extensions") if bsnap and isinstance(bsnap.get("extensions"), list) else [],
            "migrations": new_bm,
            "status": "completed",
            "error_message": None,
            "started_at": ts,
            "completed_at": ts,
            "created_at": ts,
            "updated_at": ts,
        })
        _save("schema_introspection_snapshots.json", snaps)

        br["status"] = "ready"
        br["updated_at"] = _now_iso()
        br["last_error"] = None
        _save("branches.json", branches)

        _reqlog("OK", branch_pid, None, {"branch_id": br.get("id"), "added_migrations": len(to_add)})
        return {"branch": br}
    except Exception as e:
        br["status"] = "failed"
        br["last_error"] = str(e)
        br["updated_at"] = _now_iso()
        _save("branches.json", branches)
        _reqlog("FAILED", branch_pid, "Rebase failed", {"error": str(e)})
        return _err("CONFLICT", "Rebase failed.", last_error=str(e), branch_id=br.get("id"))

