    if not isinstance(limit, int) or limit < 1 or limit > 500:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500.", field="limit")

    # Decode cursor (opaque)
    start_after = None
    if cursor is not None:
        if not isinstance(cursor, str) or len(cursor) > 4096:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            data = json.loads(raw.decode("utf-8"))
            if not isinstance(data, dict) or data.get("v") != 1:
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
            start_after = data.get("after")
            if start_after is not None and not isinstance(start_after, str):
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
        except Exception:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")

    projects = _load("projects.json")
    if not isinstance(projects, list):
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Datastore is not in the expected format.")

    # Filter
    rows = []
    for p in projects:
        if not isinstance(p, dict):
            continue
        if environment is not None and p.get("environment") != environment:
            continue
        if region is not None and p.get("region") != region:
            continue
        if status is not None and p.get("status") != status:
            continue
        if parent_project_id is not None and p.get("parent_project_id") != parent_project_id:
            continue
        rows.append(p)

    # Sort: stable, newest first by created_at, then id
    def _key(p):
        return (p.get("created_at") or "", p.get("id") or "")
    rows.sort(key=_key, reverse=True)

    # Apply cursor: start_after is an id; skip until after found
    if start_after is not None:
        idx = next((i for i, p in enumerate(rows) if p.get("id") == start_after), None)
        if idx is None:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor does not match any item in this result set.", field="cursor")
        rows = rows[idx + 1 :]

    page = rows[:limit]
    has_more = len(rows) > limit
    next_cursor = None
    if has_more and page:
        payload = {"v": 1, "after": page[-1].get("id")}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    _log("ok")
    return {
        "projects": page,
        "pagination": {
            "limit": limit,
            "total": len(rows) if start_after is None else None,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def get_project(project_id, **_extra):
    import json, os, datetime, re, time, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0198000" if __import__("os").path.isdir("./environment_mix/0198000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_used=None, error_code=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "req_" + hashlib.sha256(f"get_project|{project_id}|{now}|{random.random()}".encode("utf-8")).hexdigest()[:24],
                "endpoint": "get_project",
                "credential_used": credential_used,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    if not isinstance(project_id, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id must be a string.", field="project_id")
    if not re.match(r"^sup_proj_[0-9A-HJKMNP-TV-Z]{16,}$", project_id or ""):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id is malformed.", field="project_id")

    projects = _load("projects.json")
    if not isinstance(projects, list):
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Datastore is not in the expected format.")

    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not proj:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)

    _log("ok")
    return {"project": proj}

def update_project(project_id, name=None, region=None, status=None, **_extra):
    import json, os, datetime, re, time, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0198000" if __import__("os").path.isdir("./environment_mix/0198000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "update_project"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _reqlog(status_code, project_row_id=None, message=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + os.urandom(9).hex(),
            "endpoint": endpoint,
            "credential_id": None,
            "project_id": project_row_id,
            "status": status_code,
            "message": message,
            "extra": extra or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso(),
        })
        _save("request_logs.json", logs)

    # Validate
    if not isinstance(project_id, str) or not re.match(r"^sup_proj_[0-9A-HJKMNP-TV-Z]{16,}$", project_id or ""):
        _reqlog("VALIDATION_ERROR", None, "Malformed project_id", {"field": "project_id"})
        return _err("VALIDATION_ERROR", "Malformed project_id.", field="project_id")
    if name is not None and (not isinstance(name, str) or not name.strip()):
        _reqlog("VALIDATION_ERROR", project_id, "Invalid name", {"field": "name"})
        return _err("VALIDATION_ERROR", "name must be a non-empty string.", field="name")
    if region is not None and not isinstance(region, str):
        _reqlog("VALIDATION_ERROR", project_id, "Invalid region", {"field": "region"})
        return _err("VALIDATION_ERROR", "region must be a string.", field="region")
    if status is not None and (not isinstance(status, str) or status not in ("active", "disabled", "deleting")):
        _reqlog("VALIDATION_ERROR", project_id, "Invalid status", {"field": "status"})
        return _err("VALIDATION_ERROR", "Invalid status.", field="status", allowed=["active", "disabled", "deleting"])

    projects = _load("projects.json")
    if not isinstance(projects, list):
        _reqlog("CONFLICT", project_id, "Datastore corrupted")
        return _err("CONFLICT", "Datastore is not in the expected format.")

    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not proj:
        _reqlog("NOT_FOUND", project_id, "Project not found")
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)

    changed = False
    now = _now_iso()

    if name is not None and proj.get("name") != name:
        proj["name"] = name
        changed = True
    if region is not None and proj.get("region") != region:
        proj["region"] = region
        changed = True

    if status is not None and proj.get("status") != status:
        # enforce lifecycle transitions
        transitions = {
            "active": {"disabled", "deleting"},
            "disabled": {"active", "deleting"},
            "deleting": set(),
        }
        cur = proj.get("status")
        if cur not in transitions:
            _reqlog("CONFLICT", project_id, "Unknown current status", {"current": cur})
            return _err("CONFLICT", "Project is in an unknown lifecycle state.", current_status=cur)
        if status not in transitions[cur]:
            _reqlog("INVALID_TRANSITION", project_id, "Invalid status transition", {"from": cur, "to": status})
            return _err("INVALID_TRANSITION", "Invalid project status transition.", from_status=cur, to_status=status)
        proj["status"] = status
        changed = True

    if not changed:
        # Idempotent update: still return the row, but record the call
        _reqlog("OK", project_id, "No changes")
        return {"project": proj}

    proj["updated_at"] = now
    _save("projects.json", projects)
    _reqlog("OK", project_id, None)
    return {"project": proj}

def get_edge_function(function_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0198000" if __import__("os").path.isdir("./environment_mix/0198000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log_call(status, credential_used=None, error_code=None, error_message=None, meta=None, started_at=None):
        # This service schema provided no request-log/audit/usage collection.
        # Therefore, no durable service-dynamics logging is persisted for this tool.
        return

    started = time.time()

    # Validate inputs
    if not isinstance(function_id, str):
        _log_call("error", started_at=started, error_code="VALIDATION_ERROR", error_message="function_id must be a string")
        return _err("VALIDATION_ERROR", "function_id must be a string")

    if not re.match(r"^sup_fn_[0-9A-HJKMNP-TV-Z]{16,}$", function_id):
        _log_call("error", started_at=started, error_code="VALIDATION_ERROR", error_message="function_id is malformed")
        return _err("VALIDATION_ERROR", "function_id is malformed", field="function_id")

    edge_functions = _load("edge_functions.json")
    edge_function_versions = _load("edge_function_versions.json")
    projects = _load("projects.json")

    fn = None
    for row in edge_functions:
        if isinstance(row, dict) and row.get("id") == function_id:
            fn = row
            break

    if not fn:
        _log_call("error", started_at=started, error_code="NOT_FOUND", error_message="Edge Function not found")
        return _err("NOT_FOUND", "Edge Function not found", function_id=function_id)

    # Ambient auth: no explicit credential parameter; allow if there exists a project context.
    # Enforce minimal access guardrail: function must belong to an existing project.
    project_id = fn.get("project_id")
    proj = None
    for p in projects:
        if isinstance(p, dict) and p.get("id") == project_id:
            proj = p
            break
    if not proj:
        _log_call("error", started_at=started, error_code="UNAUTHORIZED", error_message="No accessible project for this function")
        return _err("UNAUTHORIZED", "No accessible project for this function", project_id=project_id)

    # Resolve active version (if present)
    active_version = None
    active_version_id = fn.get("active_version_id")
    if active_version_id is not None:
        for v in edge_function_versions:
            if isinstance(v, dict) and v.get("id") == active_version_id:
                # Ensure it actually belongs to this function to prevent cross-linking
                if v.get("function_id") == fn.get("id"):
                    active_version = v
                break

    # If active_version_id points nowhere or mismatches, keep metadata but expose null active_version
    # (Do not mutate on read.)
    result = {
        "edge_function": fn,
        "active_version": active_version,
    }

    _log_call("ok", started_at=started)
    return result
